selector_to_html = {"a[href=\"multi-backend-prebuilt-docker-image-install/install-tsingmicro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Tsingmicro\uff08\u6e05\u5fae\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.3.x/third_party/tsingmicro/\">tsingmicro</a><a class=\"headerlink\" href=\"#tsingmicro-tsingmicro\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (TX81)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-tx81\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later step 1.x.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-xpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab KLX <a class=\"reference internal\" href=\"#/third_party/xpu/\"><span class=\"xref myst\">xpu</span></a><a class=\"headerlink\" href=\"#klx-xpu\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (P800)<a class=\"headerlink\" href=\"#use-the-image-p800\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#install-flagtree\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagTree<a class=\"headerlink\" href=\"#install-flagtree\" title=\"Link to this heading\">#</a></h1><h2>Option 1: Install from prebuilt Docker image<a class=\"headerlink\" href=\"#option-1-install-from-prebuilt-docker-image\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from prebuilt Docker image, see the following list:</p>", "a[href=\"install-arm64-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install on Arm64 CPU<a class=\"headerlink\" href=\"#install-on-arm64-cpu\" title=\"Link to this heading\">#</a></h1><p>Before installing the FlagTree on Arm64 CPU, please read the following notes:</p>", "a[href=\"#option-1-install-from-prebuilt-docker-image\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 1: Install from prebuilt Docker image<a class=\"headerlink\" href=\"#option-1-install-from-prebuilt-docker-image\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from prebuilt Docker image, see the following list:</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-enflame.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Enflame\uff08\u71e7\u539f\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.6.x/third_party/enflame/\">enflame</a> (Triton 3.6)<a class=\"headerlink\" href=\"#enflame-enflame-triton-3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (Triton 3.6, GCU300/GCU400)<a class=\"headerlink\" href=\"#use-the-image-triton-3-6-gcu300-gcu400\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-hcu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab HYGON\uff08\u6d77\u5149\u4fe1\u606f\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.6.x/third_party/hcu/\">hcu</a> (Triton 3.6)<a class=\"headerlink\" href=\"#hygon-hcu-triton-3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (BW1000)<a class=\"headerlink\" href=\"#use-the-image-bw1000\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-iluvatar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ILUVATAR\uff08\u5929\u6570\u667a\u82af\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/iluvatar/\">iluvatar</a><a class=\"headerlink\" href=\"#iluvatar-iluvatar\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (BI-V150)<a class=\"headerlink\" href=\"#use-the-image-bi-v150\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-mthreads.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Moore Threads\uff08\u6469\u5c14\u7ebf\u7a0b\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.6.x/third_party/mthreads/\">mthreads</a> (Triton 3.6)<a class=\"headerlink\" href=\"#moore-threads-mthreads-triton-3-6\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (Triton 3.6, MTT-S5000)<a class=\"headerlink\" href=\"#use-the-image-triton-3-6-mtt-s5000\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-nv.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA &amp; AMD <a class=\"reference internal\" href=\"#/third_party/nvidia/\"><span class=\"xref myst\">nvidia</span></a> &amp; <a class=\"reference internal\" href=\"#/third_party/amd/\"><span class=\"xref myst\">amd</span></a><a class=\"headerlink\" href=\"#nvidia-amd-nvidia-amd\" title=\"Link to this heading\">#</a></h1><h2>1. Environment for build and run<a class=\"headerlink\" href=\"#environment-for-build-and-run\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#running-tests\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Running tests<a class=\"headerlink\" href=\"#running-tests\" title=\"Link to this heading\">#</a></h2><p>After installation, you can generally run the following tests. For specific backend support tests, please refer to .github/workflow/${backend_name}-build-and-test.yml in the corresponding branch.</p>", "a[href=\"#q-a\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q&amp;A<a class=\"headerlink\" href=\"#q-a\" title=\"Link to this heading\">#</a></h2><p>Q: After installation, running the program reports: version GLIBC or GLIBCXX not found</p><p>A: Check which GLIBC / GLIBCXX versions are supported by libc.so.6 and libstdc++.so.6.0.30 in your environment:</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-aipu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ARM China\uff08\u5b89\u8c0b\u79d1\u6280\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.3.x/third_party/aipu/\">aipu</a><a class=\"headerlink\" href=\"#arm-china-aipu\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (for the x64 CPU simulation environment)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-for-the-x64-cpu-simulation-environment\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later step 1.x.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-sunrise.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Sunrise\uff08\u66e6\u671b\u82af\u79d1\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/triton_v3.4.x/third_party/sunrise/\">sunrise</a><a class=\"headerlink\" href=\"#sunrise-sunrise\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (S2)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-s2\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later step 1.x.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-ascend.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huawei Ascend\uff08\u534e\u4e3a\u6607\u817e\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/blob/triton_v3.2.x/third_party/ascend\">ascend</a><a class=\"headerlink\" href=\"#huawei-ascend-ascend\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (910C)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-910c\" title=\"Link to this heading\">#</a></h3><p>This preinstalled image is created by executing the later step 1.x based on <a class=\"reference internal\" href=\"#/dockerfiles/Dockerfile-ubuntu22.04-python3.11-ascend\"><span class=\"xref myst\">Dockerfile-ubuntu22.04-python3.11-ascend</span></a> and installing FlagTree.\nIf you use this preinstalled image, you do not need to perform the later step 1.x for 910C, and for 910B you only need to perform step 1.2.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"multi-backend-prebuilt-docker-image-install/install-metax.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab MetaX\uff08\u6c90\u66e6\u80a1\u4efd\uff09<a class=\"reference internal\" href=\"#/third_party/metax/\"><span class=\"xref myst\">metax</span></a><a class=\"headerlink\" href=\"#metax-metax\" title=\"Link to this heading\">#</a></h1><h2>1. Build and run environment<a class=\"headerlink\" href=\"#build-and-run-environment\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the preinstalled image (C550)<a class=\"headerlink\" href=\"#use-the-preinstalled-image-c550\" title=\"Link to this heading\">#</a></h3><p>If you use this preinstalled image, you do not need to perform the later step 1.x.\nIf your network connection is available, you also do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#option-3-install-wheel-package\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 3: Install wheel package<a class=\"headerlink\" href=\"#option-3-install-wheel-package\" title=\"Link to this heading\">#</a></h2><p>If you do not wish to build from source, you can directly pull and install whl (partial backend support).</p>", "a[href=\"#option-2-install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Option 2: Install from source<a class=\"headerlink\" href=\"#option-2-install-from-source\" title=\"Link to this heading\">#</a></h2><p>For installing FlagTree on different backends from source, see the following list:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
